import React, { useState } from "react";
import axios from "axios";
import { FaEnvelope, FaLock, FaSignInAlt } from "react-icons/fa";
import { Link, useNavigate } from "react-router-dom";

function Login() {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    email: "",
    password: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await axios.post("http://127.0.0.1:8000/login", formData);
      alert(response.data.message);

      localStorage.setItem("user_id", response.data.user_id);
      localStorage.setItem("user_name", response.data.user);
      localStorage.setItem("role", response.data.role);

      if (response.data.role === "teacher") {
        navigate("/teacher-dashboard");
      } else {
        navigate("/student-dashboard");
      }
    } catch (error) {
      console.error(error);
      alert("Login failed");
    }
  };

  return (
    <div style={{ textAlign: "center" }}>
      <h2 style={{ color: "#4a148c", marginBottom: "20px" }}>Login</h2>

      <form
        onSubmit={handleSubmit}
        style={{
          maxWidth: "400px",
          margin: "0 auto",
          display: "flex",
          flexDirection: "column",
          gap: "15px"
        }}
      >
        <div style={{ display: "flex", alignItems: "center", border: "1px solid #ccc", borderRadius: "10px", padding: "10px" }}>
          <FaEnvelope style={{ marginRight: "10px", color: "#7b1fa2" }} />
          <input
            type="email"
            name="email"
            placeholder="Enter Email"
            onChange={handleChange}
            style={{ border: "none", outline: "none", width: "100%" }}
          />
        </div>

        <div style={{ display: "flex", alignItems: "center", border: "1px solid #ccc", borderRadius: "10px", padding: "10px" }}>
          <FaLock style={{ marginRight: "10px", color: "#7b1fa2" }} />
          <input
            type="password"
            name="password"
            placeholder="Enter Password"
            onChange={handleChange}
            style={{ border: "none", outline: "none", width: "100%" }}
          />
        </div>

        <button
          type="submit"
          style={{
            background: "#7b1fa2",
            color: "white",
            border: "none",
            padding: "12px",
            borderRadius: "10px",
            fontWeight: "bold",
            cursor: "pointer"
          }}
        >
          <FaSignInAlt /> Login
        </button>
      </form>
      <button
  onClick={handleLogout}
  style={{
    background: "#7b1fa2",
    color: "#fff",
    border: "none",
    padding: "8px 14px",
    borderRadius: "8px",
    cursor: "pointer",
    display: "flex",
    alignItems: "center",
    gap: "6px"
  }}
>
  <FaSignOutAlt />
  Logout
</button>

      <p style={{ marginTop: "15px" }}>
        Don’t have an account? <Link to="/signup">Signup</Link>
      </p>
    </div>
  );
}

export default Login;
